   824  struct Chain
   825  {
   826    inline void apply (hb_aat_apply_context_t *c) const
   827    {
   828      uint32_t flags = defaultFlags;
   829      {
   830        /* Compute applicable flags.  TODO Should move this to planning
   831         * stage and take user-requested features into account. */
   832        unsigned int count = featureCount;
   833        for (unsigned i = 0; i < count; i++)
   834        {
   835          const Feature &feature = featureZ[i];
   836          if (false) /* XXX Check if feature enabled... */
   837          {
   838            flags &= feature.disableFlags;
   839            flags |= feature.enableFlags;
   840          }
   841        }
   842      }
   843
   844      const ChainSubtable *subtable = &StructAtOffset<ChainSubtable> (&featureZ, featureZ[0].static_size * featureCount);
   845      unsigned int count = subtableCount;
   846      for (unsigned int i = 0; i < count; i++)
   847      {
   848        bool reverse;
   849
   850        if (!(subtable->subFeatureFlags & flags))
   851          goto skip;
   852
   853        if (!(subtable->coverage & ChainSubtable::AllDirections) &&
   854            HB_DIRECTION_IS_VERTICAL (c->buffer->props.direction) !=
   855            bool (subtable->coverage & ChainSubtable::Vertical))
   856          goto skip;
   857
   858        /* Buffer contents is always in logical direction.  Determine if
   859         * we need to reverse before applying this subtable.  We reverse
   860         * back after if we did reverse indeed.
   861         *
   862         * Quoting the spac:
   863         * """
   864         * Bits 28 and 30 of the coverage field control the order in which
   865         * glyphs are processed when the subtable is run by the layout engine.
   866         * Bit 28 is used to indicate if the glyph processing direction is
   867         * the same as logical order or layout order. Bit 30 is used to
   868         * indicate whether glyphs are processed forwards or backwards within
   869         * that order.
   870
   871                  Bit 30  Bit 28  Interpretation for Horizontal Text
   872                  0       0       The subtable is processed in layout order
   873                                  (the same order as the glyphs, which is
   874                                  always left-to-right).
   875                  1       0       The subtable is processed in reverse layout order
   876                                  (the order opposite that of the glyphs, which is
   877                                  always right-to-left).
   878                  0       1       The subtable is processed in logical order
   879                                  (the same order as the characters, which may be
   880                                  left-to-right or right-to-left).
   881                  1       1       The subtable is processed in reverse logical order
   882                                  (the order opposite that of the characters, which
   883                                  may be right-to-left or left-to-right).
   884         */
   885        reverse = subtable->coverage & ChainSubtable::Logical ?
   886                  bool (subtable->coverage & ChainSubtable::Backwards) :
   887                  bool (subtable->coverage & ChainSubtable::Backwards) !=
   888                  HB_DIRECTION_IS_BACKWARD (c->buffer->props.direction);
   889
   890        if (!c->buffer->message (c->font, "start chain subtable %d", c->lookup_index))
   891          goto skip;
   892
   893        if (reverse)
   894          c->buffer->reverse ();
   895
   896        c->sanitizer.set_object (*subtable);
   897
   898        subtable->dispatch (c);
   899
   900        if (reverse)
   901          c->buffer->reverse ();
   902
   903        (void) c->buffer->message (c->font, "end chain subtable %d", c->lookup_index);
   904
   905        if (unlikely (!c->buffer->successful)) return;
   906
   907      skip:
   908        subtable = &StructAfter<ChainSubtable> (*subtable);
   909        c->set_lookup_index (c->lookup_index + 1);
   910      }
   911    }
